\label{tab:per_class_recall}
\begin{tabular}{@{}lcccc@{}}
\toprule
Cell & d0 & d1 & d2 & d3 \\
\midrule
Pythia, nuc.       & 99 & 82 & 59 & 76 \\
Pythia, $\tau$     & 99 & 78 & 57 & 73 \\
Pythia, top-$k$    & 98 & 70 & 55 & 64 \\
